<?php declare(strict_types=1); require_once __DIR__ . '/auth.php'; $user=require_login(); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Victor</title><link rel="stylesheet" href="style.css"></head><body><header><div><p class="eyebrow">LIBERATE DE TUS DEUDAS.CL</p><h1>Panel de conversaciones</h1><small><?= htmlspecialchars($user['username'].' · '.$user['role']) ?></small></div><a href="index.php?logout=1">Salir</a></header><main class="layout"><section class="card"><div class="section-title"><h2>Clientes</h2><input id="client-search" placeholder="Buscar teléfono o nombre"></div><div id="clients">Cargando...</div></section><section class="card"><div class="section-title"><h2 id="selected">Selecciona un cliente</h2><div><select id="status"><option value="new">Nuevo</option><option value="open">Abierto</option><option value="pending">Pendiente</option><option value="closed">Cerrado</option></select><button id="save">Guardar</button></div></div><textarea id="notes" placeholder="Notas internas"></textarea><div id="conversation" class="conversation"></div><?php if ($user['role']==='victor'): ?><form id="reply"><textarea required placeholder="Responder por WhatsApp"></textarea><button>Enviar respuesta</button></form><?php endif; ?></section></main><script>
const csrf=<?=json_encode(csrf_token())?>,clients=document.querySelector('#clients');let current=null,currentClient=null;
async function loadClients(){const q=encodeURIComponent(document.querySelector('#client-search').value);const d=await (await fetch('api/clients.php?q='+q)).json();clients.innerHTML=d.data.map(c=>`<button class="client" data-phone="${c.phone}"><b>${esc(c.name||'Sin nombre')}</b><small>${esc(c.phone)} · ${esc(c.status||'new')}</small></button>`).join('')||'<p>Sin clientes.</p>';clients.querySelectorAll('.client').forEach(b=>b.onclick=()=>openChat(b.dataset.phone,d.data.find(c=>c.phone===b.dataset.phone)));}
async function openChat(phone,c){current=phone;currentClient=c;document.querySelector('#selected').textContent=c.name||phone;document.querySelector('#status').value=c.status||'new';document.querySelector('#notes').value=c.notes||'';const d=await (await fetch('api/conversations.php?phone='+encodeURIComponent(phone))).json();document.querySelector('#conversation').innerHTML=d.data.map(m=>`<p class="bubble ${m.role}">${esc(m.content)}</p>`).join('')||'<p>Sin mensajes.</p>';}
function esc(s){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));}
</script></body></html>
